<?php

declare(strict_types=1);

require_once __DIR__.'/PlaybillPublicationBuilder.php';

final class PlaybillPublicRenderer
{
    public static function render(string $basePath,?array $pb,array $sections,array $cast,array $staff,array $sponsors):never
    {
        $u=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(?string $v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');header('Content-Type:text/html; charset=utf-8');header('X-Robots-Tag: noindex, nofollow');
        if(!$pb){http_response_code(404);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Playbill unavailable · CTSMD</title><link rel="stylesheet" href="<?=$u('/assets/css/playbill-pages.css')?>"></head><body class="pbr-body"><main class="pbr-unavailable"><h1>This Playbill is unavailable.</h1><p>It may be unpublished or the address may be incorrect.</p></main></body></html><?php exit;}
        $title=(string)($pb['display_title']?:$pb['production_title']);$slug=rawurlencode((string)$pb['public_slug']);$pages=PlaybillPublicationBuilder::build($pb,$sections,$cast,$staff,$sponsors);$total=count($pages);$canonical=self::absoluteUrl($u('/playbill?slug='.$slug));?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$e($title)?> · CTSMD Digital Program</title><meta name="description" content="<?=$e($pb['public_description']?:('The digital program for '.$title))?>"><meta property="og:title" content="<?=$e($title)?>"><meta property="og:description" content="<?=$e($pb['public_description']?:$pb['cover_note'])?>"><?php if($pb['artwork_stored_file_id']):?><meta property="og:image" content="<?=$e(self::absoluteUrl($u('/playbill/asset?slug='.$slug.'&kind=artwork&id=0')))?>"><?php endif;?><link rel="canonical" href="<?=$e($canonical)?>"><link rel="stylesheet" href="<?=$u('/assets/css/playbill-pages.css?v=20261022v3')?>"></head><body class="pbr-body" data-total-pages="<?=$total?>"><header class="pbr-toolbar"><a class="pbr-brand" href="#page-1" aria-label="Go to cover">CTSMD <span>Digital Program</span></a><button type="button" data-toc-toggle aria-expanded="false" aria-controls="program-contents">Contents</button><div class="pbr-toolbar-actions"><button type="button" data-share>Share</button><button type="button" onclick="window.print()">Print / Save as PDF</button></div></header><nav class="pbr-contents" id="program-contents" aria-label="Table of contents" hidden><strong>Contents</strong><?php foreach($pages[1]['items'] as $item):?><a href="#page-<?=(int)$item['page']?>"><span><?=$e($item['title'])?></span><b><?=(int)$item['page']?></b></a><?php endforeach;?></nav><main class="pbr-reader" aria-label="<?=$e($title)?> program"><div class="pbr-spread" data-spread><?php foreach($pages as $index=>$page):$number=$index+1;self::page($page,$number,$total,$pb,$slug,$u,$e);endforeach;?></div></main><nav class="pbr-controls" aria-label="Publication navigation"><button type="button" data-prev>Previous</button><span data-page-count aria-live="polite">Page 1 of <?=$total?></span><button type="button" data-next>Next</button></nav><script defer src="<?=$u('/assets/js/playbill-reader.js?v=20261022v2')?>"></script></body></html><?php exit;
    }

    private static function page(array $page,int $number,int $total,array $pb,string $slug,callable $u,callable $e):void
    {
        $type=(string)$page['type'];?><article class="pbr-page pbr-<?=$e($type)?><?=$type==='cover'&&($pb['cover_display']??'')==='artwork_only'&&!empty($pb['artwork_stored_file_id'])?' pbr-cover-art-only':''?>" id="page-<?=$number?>" data-page="<?=$number?>" aria-label="Page <?=$number?> of <?=$total?>"<?=$number===1?'':' hidden'?>><?php if($type==='cover'):?><?php $artOnly=($pb['cover_display']??'artwork_and_text')==='artwork_only'&&!empty($pb['artwork_stored_file_id']);?><?php if($pb['artwork_stored_file_id']):?><img class="pbr-cover-art" src="<?=$u('/playbill/asset?slug='.$slug.'&kind=artwork&id=0')?>" alt="<?=$e($page['title'])?> production artwork"><?php endif;?><?php if(!$artOnly):?><div class="pbr-cover-copy"><small>CHILDREN'S THEATRE OF SOUTHERN MARYLAND</small><h1><?=$e($page['title'])?></h1><h2><?=$e($pb['subtitle']?:$pb['season'])?></h2><?php if($pb['cover_note']):?><p><?=$e($pb['cover_note'])?></p><?php endif;?></div><?php endif;?><?php else:?><header class="pbr-running"><span>CTSMD</span><span><?=$e($page['title'])?></span></header><div class="pbr-page-content"><?php self::content($page,$slug,$u,$e);?></div><footer class="pbr-folio"><span><?=$e((string)($pb['display_title']?:$pb['production_title']))?></span><b><?=$number?></b></footer><?php endif;?></article><?php
    }

    private static function content(array $page,string $slug,callable $u,callable $e):void
    {
        $type=$page['type'];if($type==='contents'){?><p class="pbr-kicker">YOUR PROGRAM</p><h2>Contents</h2><div class="pbr-toc-list"><?php foreach($page['items'] as $item):?><a href="#page-<?=(int)$item['page']?>"><span><?=$e($item['title'])?></span><i></i><b><?=(int)$item['page']?></b></a><?php endforeach;?></div><?php return;}
        ?><p class="pbr-kicker"><?=$e(strtoupper(str_replace('-',' ',(string)($page['section_type']??$type))))?></p><h2><?=$e($page['title'])?></h2><?php
        if($type==='cast-credits'){?><div class="pbr-credits"><?php foreach($page['items'] as $m):?><div><b><?=$e($m['display_name'])?></b><span><?=$e($m['role_title']?:'Company')?></span></div><?php endforeach;?></div><?php }
        elseif($type==='cast-bios'){?><div class="pbr-bios"><?php foreach($page['items'] as $m):?><section class="<?=$m['headshot_stored_file_id']?'has-headshot':'no-headshot'?>"><?php if($m['headshot_stored_file_id']):?><img src="<?=$u('/playbill/asset?slug='.$slug.'&kind=headshot&id='.(int)$m['user_id'])?>" alt="Portrait of <?=$e($m['display_name'])?>"><?php endif;?><div><h3><?=$e($m['display_name'])?></h3><strong><?=$e($m['role_title'])?></strong><p><?=$e($m['biography'])?></p><?php if($m['photographer_credit']):?><small>Photo: <?=$e($m['photographer_credit'])?></small><?php endif;?></div></section><?php endforeach;?></div><?php }
        elseif($type==='team'){?><div class="pbr-credits"><?php foreach($page['items'] as $m):?><div><b><?=$e($m['name'])?></b><span><?=$e($m['participation_role'])?></span></div><?php endforeach;?></div><?php }
        elseif($type==='editorial'){?><div class="pbr-editorial"><?=self::safeEditorial($page['body'],$e)?></div><?php }
        elseif($type==='sponsors'){?><div class="pbr-sponsors"><?php foreach($page['items'] as $s):$kind=$s['advertisement_stored_file_id']?'sponsor-ad':'sponsor';?><section class="<?=$s['tier']==='premium'?'is-premium':''?>"><?php if($s[$kind==='sponsor-ad'?'advertisement_stored_file_id':'logo_stored_file_id']):?><img src="<?=$u('/playbill/asset?slug='.$slug.'&kind='.$kind.'&id='.(int)$s['id'])?>" alt="<?=$e($s['name'])?> artwork"><?php endif;?><h3><?=$e($s['name'])?></h3><span><?=$e($s['placement_label'])?></span><p><?=$e($s['public_description'])?></p><?php if($s['website_url']):?><a target="_blank" rel="noopener noreferrer" href="<?=$e($s['website_url'])?>"><?=$e($s['cta_label']?:'Visit sponsor')?></a><?php endif;?></section><?php endforeach;?></div><?php }
        elseif($type==='closing'){?><div class="pbr-closing"><p>Thank you for supporting live theatre in Southern Maryland.</p><?php foreach($page['links'] as $link):?><a target="_blank" rel="noopener noreferrer" href="<?=$e($link['url'])?>"><?=$e($link['label'])?></a><?php endforeach;?><button type="button" data-share>Share this Playbill</button></div><?php }
    }

    private static function safeEditorial(string $text,callable $e):string{$blocks=preg_split('/\n{2,}/',trim($text))?:[];$html='';foreach($blocks as $block){$lines=preg_split('/\R/',trim($block))?:[];if($lines&&array_reduce($lines,static fn(bool $ok,string $line):bool=>$ok&&str_starts_with($line,'- '),true)){$html.='<ul>';foreach($lines as $line)$html.='<li>'.$e(substr($line,2)).'</li>';$html.='</ul>';}else$html.='<p>'.nl2br($e($block)).'</p>';}return$html;}
    private static function absoluteUrl(string $path):string{return((!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost').$path;}
}
